import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import type { BuildingDef, CityMap } from "@afterfall/world";
import { CellKind, abandonedVehicles } from "@afterfall/world";
import { outlineOf } from "./buildingBatch";
import { LITTER_KINDS, type LitterKind } from "./litter";

/** The kit shipped in `public/art/props`, generated by `tools/blender/props.py`. */
export const PROP_KINDS = ["car", "dumpster", "fence", "sign", "lamp", "barrier", "ambulance", "container", "crates"] as const;
export type PropKind = (typeof PROP_KINDS)[number];

/** The rooftop kit, generated by `tools/blender/roof_props.py`. */
export const ROOF_KINDS = ["roof_tank", "roof_ac", "roof_stairs", "roof_antenna", "roof_vent"] as const;
export type RoofKind = (typeof ROOF_KINDS)[number];

export interface PropPlacement {
  x: number;
  z: number;
  /** Height of the base: 0 on the street, the roof's height on top of a building. */
  y?: number;
  /** Yaw in radians, so a car sits along the street instead of across it. */
  rot: number;
  scale: number;
  doorOpen?: boolean;
}

const MAX_PER_KIND = 70;
/** Conservative half extents of the authored kit in its local X/Z plane. */
const FOOTPRINT: Record<PropKind, [number, number]> = {
  car: [1.05, 2.23],
  ambulance: [1.18, 2.65],
  container: [1.3, 3.1],
  dumpster: [1.16, 0.84],
  barrier: [1.02, 0.34],
  fence: [1.14, 0.18],
  crates: [0.7, 0.6],
  lamp: [0.3, 0.3],
  sign: [0.7, 0.2],
};

/**
 * A soft radial glow, drawn once to a canvas. Used as the halo on every lamp
 * head: an additive quad costs one draw call for the whole city and no shadow,
 * which is what keeps the night readable without a bloom pass.
 */
function glowTexture(): THREE.Texture | null {
  if (typeof document === "undefined") return null;
  const size = 64;
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext("2d");
  if (!ctx) return null;
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, "rgba(255,214,150,1)");
  g.addColorStop(0.35, "rgba(255,186,110,0.45)");
  g.addColorStop(1, "rgba(255,170,90,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

/** Deterministic hash, so the same seed always dresses the same city. */
function hash(a: number, b: number, seed: number): number {
  let h = a * 374761393 + b * 668265263 + seed * 2147483647;
  h = (h ^ (h >>> 13)) * 1274126177;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Footprint radius of each rooftop piece, for spacing and for keeping off the parapet. */
const ROOF_RADIUS: Record<RoofKind, number> = { roof_tank: 1.3, roof_ac: 0.9, roof_stairs: 2.2, roof_antenna: 0.5, roof_vent: 0.4 };
/** The parapet is 0.3 m thick: keep this much clear inside the outline. */
const ROOF_MARGIN = 0.6;
const MAX_ROOF_PER_KIND = 400;
const COMMERCIAL = new Set(["shop", "supermarket", "pharmacy", "office", "hospital", "school", "police", "warehouse"]);

function insidePolygon(poly: { x: number; y: number }[], x: number, y: number): boolean {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i];
    const b = poly[j];
    if (a.y > y !== b.y > y && x < ((b.x - a.x) * (y - a.y)) / (b.y - a.y) + a.x) inside = !inside;
  }
  return inside;
}

function edgeDistance(poly: { x: number; y: number }[], x: number, y: number): number {
  let best = Infinity;
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i];
    const b = poly[(i + 1) % poly.length];
    const ex = b.x - a.x;
    const ey = b.y - a.y;
    const l2 = ex * ex + ey * ey || 1;
    const t = Math.max(0, Math.min(1, ((x - a.x) * ex + (y - a.y) * ey) / l2));
    best = Math.min(best, Math.hypot(x - a.x - ex * t, y - a.y - ey * t));
  }
  return best;
}

/**
 * Dresses the roofs, which is most of what the RTS camera sees: a stair
 * bulkhead on buildings of three floors or more, water tanks on homes, AC
 * units on shops and offices, vents and the odd antenna everywhere. Pieces
 * stay inside the parapet, keep clear of each other and turn with the
 * building's first wall, so they line up with it. Deterministic per seed.
 */
export function placeRoofProps(buildings: BuildingDef[], seed = 1): Map<RoofKind, PropPlacement[]> {
  const out = new Map<RoofKind, PropPlacement[]>();
  for (const b of buildings) {
    const poly = outlineOf(b);
    const a = poly[0];
    const c = poly[1];
    const yaw = -Math.atan2(c.y - a.y, c.x - a.x);
    const minX = Math.min(...poly.map((p) => p.x));
    const maxX = Math.max(...poly.map((p) => p.x));
    const minY = Math.min(...poly.map((p) => p.y));
    const maxY = Math.max(...poly.map((p) => p.y));
    const commercial = COMMERCIAL.has(b.type);
    const h = (k: number) => hash(b.index * 7919 + k, b.index * 104729 + k * 31, seed + 101);

    const wants: RoofKind[] = [];
    if (b.floors >= 3 && h(1) < 0.75) wants.push("roof_stairs");
    if (!commercial && b.floors >= 2 && h(2) < 0.55) wants.push("roof_tank");
    const acs = commercial ? 1 + Math.floor(h(3) * Math.min(4, b.area / 120)) : h(3) < 0.3 ? 1 : 0;
    for (let i = 0; i < acs; i++) wants.push("roof_ac");
    if (h(4) < 0.5) wants.push("roof_vent");
    if (h(5) < 0.22) wants.push("roof_antenna");

    const placed: { x: number; y: number; r: number }[] = [];
    wants.forEach((kind, n) => {
      const list = out.get(kind) ?? [];
      if (list.length >= MAX_ROOF_PER_KIND) return;
      const r = ROOF_RADIUS[kind];
      // A few tries at a free spot; a crowded or narrow roof just gets less.
      for (let t = 0; t < 8; t++) {
        const x = minX + (maxX - minX) * h(20 + n * 13 + t);
        const y = minY + (maxY - minY) * h(40 + n * 17 + t);
        if (!insidePolygon(poly, x, y) || edgeDistance(poly, x, y) < r + ROOF_MARGIN) continue;
        if (placed.some((p) => Math.hypot(p.x - x, p.y - y) < p.r + r + 0.3)) continue;
        placed.push({ x, y, r });
        list.push({ x, z: y, y: b.height, rot: yaw + Math.floor(h(60 + n) * 4) * (Math.PI / 2), scale: 0.92 + h(80 + n) * 0.16 });
        out.set(kind, list);
        return;
      }
    });
  }
  return out;
}

/** What the block itself is: the props should say the same thing the buildings do. */
export interface BlockContext {
  industrial: boolean;
  commercial: boolean;
  pharmacy: boolean;
}

/**
 * Which prop belongs on a given side of the street. A residential block gets the
 * everyday furniture; an industrial one gets containers, a commercial one crates, and a
 * block with a pharmacy gets the ambulance that never left.
 */
function pickKind(r: number, ctx: BlockContext): PropKind {
  if (ctx.industrial && r < 0.3) return "container";
  if (ctx.commercial && r < 0.16) return "crates";
  if (r < 0.34) return "car";
  if (r < 0.52) return "barrier";
  if (r < 0.66) return "dumpster";
  if (r < 0.8) return "lamp";
  if (r < 0.92) return "sign";
  return "fence";
}

/** The zone most of a block's buildings belong to, plus whether it has a pharmacy. */
function blockContext(city: CityMap, x0: number, z0: number, x1: number, z1: number): BlockContext {
  let industrial = 0;
  let commercial = 0;
  let residential = 0;
  let pharmacy = false;
  for (const b of city.buildings) {
    const cx = b.rect.x + b.rect.w / 2;
    const cz = b.rect.y + b.rect.h / 2;
    if (cx < x0 || cx > x1 || cz < z0 || cz > z1) continue;
    if (b.zone === "industrial") industrial++;
    else if (b.zone === "commercial") commercial++;
    else residential++;
    if (b.type === "pharmacy") pharmacy = true;
  }
  return {
    industrial: industrial > commercial && industrial >= residential,
    commercial: commercial > residential,
    pharmacy,
  };
}

/**
 * Dresses sidewalks with furniture where the navigation grid is free, then
 * adds road vehicles from the shared world placement used by collision.
 */
export function placeProps(
  city: CityMap,
  grid: { kind: Int8Array | Uint8Array; cellOf(x: number, y: number): number; cell: number },
  seed = 1,
): Map<PropKind, PropPlacement[]> {
  const out = new Map<PropKind, PropPlacement[]>();
  const pitch = city.blockSize + city.roadWidth;
  const step = 7.5;

  for (let bj = 0; bj < city.blocksY; bj++) {
    for (let bi = 0; bi < city.blocksX; bi++) {
      const x0 = city.roadWidth + bi * pitch;
      const z0 = city.roadWidth + bj * pitch;
      const x1 = x0 + city.blockSize;
      const z1 = z0 + city.blockSize;
      const ctx = blockContext(city, x0, z0, x1, z1);
      // One ambulance per block with a pharmacy, on the first slot that fits: a dice roll
      // per prop left most pharmacy blocks without the one thing that says "hospital".
      let wantAmbulance = ctx.pharmacy;
      const sides: [number, number, number, number, number][] = [
        // x0, z0, dx, dz, rot: the prop faces the street it borders.
        [x0, z0, 1, 0, 0],
        [x1, z0, 0, 1, Math.PI / 2],
        [x1, z1, -1, 0, Math.PI],
        [x0, z1, 0, -1, -Math.PI / 2],
      ];
      // The side index goes into the hash: without it all four sides of a block get
      // the same props, which reads as a pattern from above.
      sides.forEach(([sx, sz, dx, dz, rot], si) => {
        const len = Math.abs(dx) ? x1 - x0 : z1 - z0;
        for (let t = 3; t < len - 3; t += step) {
          const wobble = hash(bi * 31 + t, bj * 17 + t + si * 101, seed) * 3;
          const r = hash(bi * 7 + t, bj * 13 + t + si * 57, seed + 5);
          if (r > 0.42) continue; // leave the street breathing: density, not clutter
          const kind = wantAmbulance ? "ambulance" : pickKind(hash(bi * 3 + t, bj * 11 + t + si * 43, seed + 9), ctx);
          if (kind === "car" || kind === "ambulance") {
            wantAmbulance = false;
            continue;
          }
          const list = out.get(kind) ?? [];
          if (list.length >= MAX_PER_KIND) continue;
          const longitudinal = kind === "container";
          const yaw = rot + (longitudinal ? Math.PI / 2 : 0) + (hash(bi + t, bj + t, seed + 11) - 0.5) * 0.3;
          const scale = (0.9 + hash(bi + t, bj + t, seed + 13) * 0.25) * (kind === "container" ? 0.72 : 1);
          const [halfX, halfZ] = FOOTPRINT[kind].map((v) => v * scale);
          const c = Math.cos(yaw),
            s = Math.sin(yaw);
          const extentX = Math.abs(c) * halfX + Math.abs(s) * halfZ;
          const extentZ = Math.abs(s) * halfX + Math.abs(c) * halfZ;
          const inset = (dx ? extentZ : extentX) + 0.25;
          const x = sx + dx * (t + wobble) - dz * inset;
          const z = sz + dz * (t + wobble) + dx * inset;
          if (x - extentX < x0 || x + extentX > x1 || z - extentZ < z0 || z + extentZ > z1) continue;
          // Check the complete footprint, including its edges, against walls and doors.
          const nx = Math.ceil((halfX * 4) / grid.cell),
            nz = Math.ceil((halfZ * 4) / grid.cell);
          let free = true;
          for (let ix = 0; ix <= nx && free; ix++)
            for (let iz = 0; iz <= nz; iz++) {
              const lx = -halfX + (2 * halfX * ix) / nx,
                lz = -halfZ + (2 * halfZ * iz) / nz;
              if (grid.kind[grid.cellOf(x + c * lx + s * lz, z - s * lx + c * lz)] !== CellKind.Free) {
                free = false;
                break;
              }
            }
          if (
            !free ||
            city.buildings.some((b) => {
              const ex = b.entrance.x - x,
                ez = b.entrance.y - z;
              return Math.abs(c * ex - s * ez) < halfX + 1.3 && Math.abs(s * ex + c * ez) < halfZ + 1.3;
            })
          )
            continue;
          list.push({ x, z, rot: yaw, scale });

          out.set(kind, list);
        }
      });
    }
  }
  const vehicles = abandonedVehicles(city);
  for (const kind of ["car", "ambulance"] as const) {
    const cars = vehicles.filter((p) => p.kind === kind);
    if (cars.length) out.set(kind, cars);
  }
  return out;
}

export interface PropScene {
  /** Meshes added to the scene, so they can be dropped when the city changes. */
  meshes: THREE.Object3D[];
  instances: number;
  drawCalls: number;
}

/**
 * Loads the kit and instances it. Every child mesh of a GLB becomes its own
 * InstancedMesh, which keeps the multi-material props (a car has body, glass
 * and tyres) at one draw call each without merging materials.
 */
export async function loadProps(
  baseUrl: string,
  placements: Map<PropKind | RoofKind | LitterKind, PropPlacement[]>,
  onReady: (scene: PropScene) => void,
): Promise<void> {
  const loader = new GLTFLoader();
  const meshes: THREE.Object3D[] = [];
  let instances = 0;
  let drawCalls = 0;
  let halo: THREE.InstancedMesh | null = null;
  const glow = glowTexture();
  const matrix = new THREE.Matrix4();
  const quat = new THREE.Quaternion();
  const pos = new THREE.Vector3();
  const scale = new THREE.Vector3();

  await Promise.all(
    [...PROP_KINDS, ...ROOF_KINDS, ...LITTER_KINDS].map(async (kind) => {
      const list = placements.get(kind);
      if (!list || list.length === 0) return;
      let gltf;
      try {
        gltf = await loader.loadAsync(`${baseUrl}art/props/${kind}.glb`);
      } catch {
        return; // a missing prop must never take the scene down
      }
      gltf.scene.updateMatrixWorld(true);
      gltf.scene.traverse((child) => {
        if (!(child instanceof THREE.Mesh)) return;
        const geo = child.geometry.clone();
        geo.applyMatrix4(child.matrixWorld);
        const src = child.material as THREE.MeshStandardMaterial;
        const mat = new THREE.MeshStandardMaterial({
          name: src.name,
          color: src.color ? src.color.clone() : new THREE.Color(0x888888),
          vertexColors: !!geo.getAttribute("color"),
          roughness: src.roughness ?? 0.85,
          metalness: src.metalness ?? 0,
          flatShading: true,
        });
        const inst = new THREE.InstancedMesh(geo, mat, list.length);
        inst.name = `prop-${kind}-${src.name}`;
        // Keep shadows on large silhouettes (a rubble heap without one floats). The
        // packed palette limits each roof piece to one batch, including the shadow pass.
        inst.castShadow = ["car", "ambulance", "barrier", "dumpster", "roof_tank", "roof_stairs", "litter_rubble"].includes(kind);
        inst.receiveShadow = true;
        inst.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        list.forEach((p, i) => {
          pos.set(p.x, p.y ?? 0, p.z);
          quat.setFromAxisAngle(new THREE.Vector3(0, 1, 0), p.rot);
          scale.setScalar(p.scale);
          matrix.compose(pos, quat, scale);
          inst.setMatrixAt(i, matrix);
          if (src.name === "surface_paint" && (kind === "car" || kind === "container")) {
            const palette = kind === "car" ? [0xaeb9b4, 0x768b99, 0xb79b73, 0x9b6250, 0x879077] : [0x9b604a, 0x6c8582, 0x8d9276];
            inst.setColorAt(i, new THREE.Color(palette[Math.floor(hash(p.x, p.z, 41) * palette.length)]));
          }
        });
        inst.instanceMatrix.needsUpdate = true;
        inst.computeBoundingSphere();
        meshes.push(inst);
        instances += list.length;
        drawCalls += 1;

        // Every lamp gets a halo at head height; one instanced mesh for all of
        // them, so the night gains light that costs a single draw call.
        if (kind === "lamp" && glow && !halo) {
          const haloMat = new THREE.MeshBasicMaterial({
            map: glow,
            transparent: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            side: THREE.DoubleSide,
          });
          halo = new THREE.InstancedMesh(new THREE.PlaneGeometry(1, 1), haloMat, list.length);
          halo.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
          halo.frustumCulled = false;
          list.forEach((pl, i) => {
            pos.set(pl.x + Math.cos(pl.rot) * 1.01 * pl.scale, (pl.y ?? 0) + 5.34 * pl.scale, pl.z - Math.sin(pl.rot) * 1.01 * pl.scale);
            quat.setFromAxisAngle(new THREE.Vector3(0, 1, 0), pl.rot);
            scale.setScalar(2.6 * pl.scale);
            matrix.compose(pos, quat, scale);
            halo!.setMatrixAt(i, matrix);
          });
          halo.instanceMatrix.needsUpdate = true;
          halo.computeBoundingSphere();
          meshes.push(halo);
          drawCalls += 1;
        }
      });
    }),
  );

  const openCars = (placements.get("car") ?? []).filter((p) => p.doorOpen);
  if (openCars.length) {
    // A dark opening covers the closed side panel; the detached leaf swings
    // around the front hinge. The world footprint includes the open leaf.
    for (const [name, size, local, yaw, color] of [
      ["opening", [0.035, 1.05, 1.05], [0.915, 0.9, -0.25], 0, 0x111b1d],
      ["panel", [0.07, 0.52, 1.05], [1.39, 0.61, -0.55], 1.12, 0x738077],
      ["window", [0.045, 0.49, 0.98], [1.39, 1.12, -0.55], 1.12, 0x24383d],
      ["frame", [0.07, 0.055, 1.05], [1.39, 1.39, -0.55], 1.12, 0x738077],
    ] as const) {
      const part = new THREE.InstancedMesh(
        new THREE.BoxGeometry(size[0], size[1], size[2]),
        new THREE.MeshStandardMaterial({ color, roughness: 0.8 }),
        openCars.length,
      );
      part.name = `vehicle-open-door-${name}`;
      part.castShadow = part.receiveShadow = true;
      const localMatrix = new THREE.Matrix4().makeRotationY(yaw).setPosition(local[0], local[1], local[2]);
      openCars.forEach((p, i) => {
        matrix.makeRotationY(p.rot).setPosition(p.x, 0, p.z).multiply(localMatrix);
        part.setMatrixAt(i, matrix);
      });
      part.instanceMatrix.needsUpdate = true;
      part.computeBoundingSphere();
      meshes.push(part);
      drawCalls++;
    }
  }
  onReady({ meshes, instances, drawCalls });
}
